-- ═══ CHECK CONSTRAINTS (live-only ones live here) ═══
  ai_report_requests.ai_report_requests_credits_charged_check  CHECK ((credits_charged >= 0))
  ai_report_requests.ai_report_requests_scope_type_check  CHECK ((scope_type = ANY (ARRAY['single_session'::text, 'selected_sessions'::text, 'last_7_days'::text, 'last_30_days'::text])))
  ai_report_requests.ai_report_requests_status_check  CHECK ((status = ANY (ARRAY['pending'::text, 'queued'::text, 'processing'::text, 'completed'::text, 'failed'::text])))
  ai_report_requests.ai_report_requests_tokens_spent_check  CHECK ((tokens_spent >= 0))
  credit_transactions.credit_transactions_type_check  CHECK ((type = ANY (ARRAY['purchase'::text, 'signup_bonus'::text, 'session_usage'::text, 'refund'::text, 'manual'::text])))
  learner_profile_extractions.learner_profile_extractions_confidence_check  CHECK (((confidence IS NULL) OR ((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))))
  learner_profile_extractions.learner_profile_extractions_coverage_check  CHECK ((coverage = ANY (ARRAY['none'::text, 'thin'::text, 'substantial'::text])))
  learner_profile_extractions.learner_profile_extractions_coverage_payload_check  CHECK (((coverage = 'none'::text) = learner_payload_is_empty(payload)))
  learner_progress.learner_progress_data_size  CHECK ((pg_column_size(data) < 131072))
  notifications.notifications_type_check  CHECK ((type = ANY (ARRAY['system'::text, 'welcome'::text, 'metric'::text, 'boost'::text, 'motivational'::text])))
  onboarding_responses.onboarding_responses_consent_complete  CHECK (((COALESCE(terms_consent, false) = false) OR ((terms_version IS NOT NULL) AND (terms_consent_at IS NOT NULL))))
  organisation_credits.organisation_credits_balance_minutes_check  CHECK ((balance_minutes >= 0))
  organisation_credits.organisation_credits_balance_seconds_check  CHECK ((balance_seconds >= 0))
  organisation_members.organisation_members_role_check  CHECK ((role = ANY (ARRAY['owner'::text, 'teacher'::text, 'student'::text])))
  organisation_members.organisation_members_status_check  CHECK ((status = ANY (ARRAY['active'::text, 'invited'::text, 'removed'::text])))
  referrals.referrals_status_check  CHECK ((status = ANY (ARRAY['signed_up'::text, 'completed'::text, 'expired'::text])))
  report_products.report_products_basis_check  CHECK ((basis = ANY (ARRAY['sessions'::text, 'both'::text, 'grammatica'::text])))
  report_products.report_products_credits_check  CHECK ((credits >= 0))
  review_attempts.review_attempts_grade_check  CHECK ((grade = ANY (ARRAY['again'::text, 'hard'::text, 'good'::text, 'easy'::text])))
  review_attempts.review_attempts_mode_check  CHECK ((mode = ANY (ARRAY['review'::text, 'test_typing'::text, 'test_speaking'::text])))
  review_bank_definitions.review_bank_definitions_group_check  CHECK ((group_key = ANY (ARRAY['pinned'::text, 'smart'::text, 'yours'::text])))
  review_bank_definitions.review_bank_definitions_type_check  CHECK ((bank_type = ANY (ARRAY['queue'::text, 'collection-queue'::text, 'recommendation'::text, 'user-collection'::text, 'rescue-queue'::text, 'activation-queue'::text])))
  review_bank_words.review_bank_words_source_check  CHECK ((source_type = ANY (ARRAY['system'::text, 'smart'::text, 'user'::text])))
  review_bank_words.review_bank_words_status_check  CHECK ((status = ANY (ARRAY['active'::text, 'dismissed'::text, 'promoted'::text, 'archived'::text])))
  review_sessions.review_sessions_mode_check  CHECK ((mode = ANY (ARRAY['review'::text, 'test_typing'::text, 'test_speaking'::text])))
  review_sessions.review_sessions_status_check  CHECK ((status = ANY (ARRAY['active'::text, 'completed'::text, 'abandoned'::text])))
  review_suggestion_feedback.review_suggestion_feedback_action_check  CHECK ((action = ANY (ARRAY['accepted'::text, 'dismissed'::text, 'promoted_to_yours'::text, 'not_relevant'::text, 'already_known'::text, 'save_for_later'::text])))
  review_word_relations.review_word_relations_type_check  CHECK ((relation_type = ANY (ARRAY['synonym'::text, 'near_synonym'::text, 'collocation'::text, 'derivation'::text, 'register_upgrade'::text, 'topic_neighbor'::text, 'next_step'::text])))
  review_words.review_words_last_result_check  CHECK (((last_result IS NULL) OR (last_result = ANY (ARRAY['again'::text, 'hard'::text, 'good'::text, 'easy'::text]))))
  review_words.review_words_review_state_check  CHECK ((review_state = ANY (ARRAY['new'::text, 'learning'::text, 'review'::text, 'relearning'::text, 'mastered'::text])))
  review_words.review_words_saved_origin_check  CHECK (((saved_origin IS NULL) OR (saved_origin = ANY (ARRAY['session'::text, 'manual'::text, 'smart'::text, 'import'::text]))))
  room_invites.room_invites_role_check  CHECK ((role = ANY (ARRAY['editor'::text, 'speaker'::text, 'viewer'::text])))
  room_members.room_members_role_check  CHECK ((role = ANY (ARRAY['owner'::text, 'editor'::text, 'speaker'::text, 'viewer'::text])))
  rooms.rooms_status_check  CHECK ((status = ANY (ARRAY['draft'::text, 'live'::text, 'ended'::text, 'archived'::text])))
  segment_grammar.segment_grammar_mode_check  CHECK ((mode = ANY (ARRAY['fix_grammar'::text, 'improve_clarity'::text])))
  segment_grammar.segment_grammar_status_check  CHECK ((status = ANY (ARRAY['pending'::text, 'complete'::text, 'failed'::text])))
  session_metrics_anonymous.session_metrics_anonymous_duration_seconds_check  CHECK ((duration_seconds > 0))
  token_transactions.token_transactions_type_check  CHECK ((type = ANY (ARRAY['purchase'::text, 'signup_bonus'::text, 'report_usage'::text, 'refund'::text, 'manual'::text])))
  training_card_results.training_card_results_quality_check  CHECK (((quality IS NULL) OR (quality = ANY (ARRAY[1, 3, 4, 5]))))
  training_card_results.training_card_results_result_check  CHECK (((result IS NULL) OR (result = ANY (ARRAY['again'::text, 'hard'::text, 'good'::text, 'easy'::text]))))
  training_sessions.training_sessions_accuracy_pct_check  CHECK (((accuracy_pct IS NULL) OR ((accuracy_pct >= 0) AND (accuracy_pct <= 100))))
  training_sessions.training_sessions_kind_check  CHECK ((kind = ANY (ARRAY['bank'::text, 'review'::text, 'mission'::text, 'lesson'::text, 'test'::text, 'practice'::text])))
  transcription_usage.transcription_usage_bytes_check  CHECK ((bytes > 0))
  user_ai_entitlements.user_ai_entitlements_period_type_check  CHECK ((period_type = ANY (ARRAY['once'::text, 'weekly'::text, 'monthly'::text])))
  user_ai_entitlements.user_ai_entitlements_usage_check  CHECK (((uses_allowed >= 0) AND (uses_consumed >= 0)))
  user_tasks.user_tasks_status_check  CHECK ((status = ANY (ARRAY['doing'::text, 'todo'::text, 'done'::text])))
  user_vocabulary.user_vocabulary_lang_check  CHECK ((lang = ANY (ARRAY['en'::text, 'it'::text])))
  user_wordbanks.user_wordbanks_lang_check  CHECK ((lang = ANY (ARRAY['en'::text, 'it'::text])))
  vocabulary_entries.vocabulary_entries_status_check  CHECK ((status = ANY (ARRAY['new'::text, 'learning'::text, 'known'::text, 'ignored'::text])))
  word_translations.word_translations_clean  CHECK (((translation !~ '[<>]'::text) AND (translation !~ '&(#?[a-zA-Z]+);'::text) AND (translation !~ '[.!?](\s|$)'::text) AND (translation !~ '(\s\S+){5,}'::text) AND ((length(translation) >= 2) AND (length(translation) <= 80)) AND (translation ~ '[[:alpha:]]'::text)))
  word_translations.word_translations_source  CHECK ((source = ANY (ARRAY['human'::text, 'dictionary'::text, 'machine'::text, 'ai'::text])))

