  --- policies ---
  ai_configs | Service role can manage ai_configs | cmd=ALL | roles=service_role | using=true | check=true
  ai_configs | ai_configs_service_read | cmd=SELECT | roles=service_role | using=true | check=-
  ai_report_requests | Enable insert for authenticated users only | cmd=INSERT | roles=authenticated | using=- | check=(auth.uid() = user_id)
  ai_report_requests | Users insert own requests | cmd=INSERT | roles=public | using=- | check=(auth.uid() = user_id)
  ai_report_requests | Users read own requests | cmd=SELECT | roles=public | using=(auth.uid() = user_id) | check=-
  client_errors | Allow anonymous insert | cmd=INSERT | roles=anon,authenticated | using=- | check=true
  client_errors | Service role can read client_errors | cmd=SELECT | roles=service_role | using=true | check=-
  contextual_messages | Anyone can read messages | cmd=SELECT | roles=public | using=true | check=-
  contextual_messages | Authenticated can manage messages | cmd=ALL | roles=public | using=(auth.role() = 'authenticated'::text) | check=-
  credit_transactions | Users insert credit log | cmd=INSERT | roles=public | using=- | check=(auth.uid() = user_id)
  credit_transactions | Users read own credit log | cmd=SELECT | roles=public | using=(auth.uid() = user_id) | check=-
  grammar_errors | grammar_errors_owner_all | cmd=ALL | roles=public | using=(user_id = auth.uid()) | check=(user_id = auth.uid())
  grammar_reports | Users can insert own grammar reports | cmd=INSERT | roles=public | using=- | check=(auth.uid() = user_id)
  grammar_reports | Users can read own grammar reports | cmd=SELECT | roles=public | using=(auth.uid() = user_id) | check=-
  grammar_reports | Users can update own grammar reports | cmd=UPDATE | roles=public | using=(auth.uid() = user_id) | check=-
  learner_grammar_profiles | own grammar profile insert | cmd=INSERT | roles=public | using=- | check=(auth.uid() = user_id)
